create extension if not exists pgcrypto;
create type subscription_status as enum('active','cancelled','lapsed'); create type plan_type as enum('monthly','yearly'); create type draw_status as enum('draft','published'); create type logic_type as enum('random','algorithmic'); create type verification_status as enum('pending','approved','rejected'); create type payment_status as enum('pending','paid');
create table charities(id uuid primary key default gen_random_uuid(),name text not null,description text not null,logo_url text,total_raised numeric(12,2) not null default 0,created_at timestamptz default now());
create table profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,subscription_status subscription_status not null default 'lapsed',plan plan_type,charity_id uuid references charities(id) on delete set null,contribution_percent int not null default 10 check(contribution_percent>=10 and contribution_percent<=100),created_at timestamptz default now());
create table scores(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,score int not null check(score between 1 and 45),date date not null,created_at timestamptz default now(),unique(user_id,date));
create table draws(id uuid primary key default gen_random_uuid(),winning_numbers int[] not null,draw_date date not null,total_pool numeric(12,2) not null default 0,rollover_amount numeric(12,2) not null default 0,status draw_status not null default 'draft',logic_type logic_type not null,created_at timestamptz default now());
create table winners(id uuid primary key default gen_random_uuid(),draw_id uuid not null references draws(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,match_count int not null,prize_amount numeric(12,2) not null,verification_status verification_status not null default 'pending',proof_url text,payment_status payment_status not null default 'pending',created_at timestamptz default now());
create index scores_user_date_idx on scores(user_id,date desc); create index winners_draw_idx on winners(draw_id); create index profiles_status_idx on profiles(subscription_status);
alter table charities enable row level security; alter table profiles enable row level security; alter table scores enable row level security; alter table draws enable row level security; alter table winners enable row level security;
create policy "public charities" on charities for select using(true); create policy "own profile" on profiles for select using(auth.uid()=id); create policy "own scores" on scores for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "published draws" on draws for select using(status='published'); create policy "own winners" on winners for select using(auth.uid()=user_id);
create or replace function handle_new_user() returns trigger language plpgsql security definer as $$ begin insert into public.profiles(id,email) values(new.id,new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure handle_new_user();
insert into charities(name,description,logo_url) values ('The Green Horizon Fund','Supports accessible outdoor recreation and community wellbeing.',''),('Fairway Futures','Funds youth sport, mentorship and equipment access.',''),('Open Doors Foundation','Creates practical pathways into education, work and healthy activity.','');
alter table profiles add column if not exists stripe_customer_id text;
create table if not exists donations(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),charity_id uuid references charities(id),amount numeric(12,2) not null,created_at timestamptz default now());
